216	        // 'address') back on the DTO so it is what gets persisted and compared. Reject the create
217	        // when no address is supplied in either form (see normalizeAddresses).
218	        if (!normalizeAddresses(ownerFieldsDto)) {
219	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
220	        }
221	        // Reject the create when the owner's city is already at capacity, i.e. it already
222	        // contains 50 or more owners (compared case-insensitively).
223	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= 50) {
224	            return new ResponseEntity<>(HttpStatus.CONFLICT);
225	        }
