227	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
228	        if (normalizedTelephone == null) {
229	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
230	        }
231	        ownerFieldsDto.setTelephone(normalizedTelephone);
232	        // Consolidated duplicate detection. All duplicate checks are now expressed through the
233	        // single derived identity key: the SHA-256 hex of
234	        // '<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>' (see OwnerMapper#identityKey).
235	        // A create is rejected with 409 only when the new owner's identity key collides with an
236	        // existing (non-deleted) owner's. Because the telephone is part of the key, two owners with
237	        // the same last name and postcode but different telephones no longer collide — they are
238	        // created (and may be flagged as a soft match below), not rejected. The former separate
239	        // household-duplicate 409 keyed on the computed householdId no longer applies.
240	        Owner candidate = ownerMapper.toOwner(ownerFieldsDto);
241	        String identityKey = ownerMapper.identityKey(candidate);
242	        boolean identityInUse = this.clinicService.findAllOwners().stream()
243	            .filter(existing -> !existing.isDeleted())
244	            .anyMatch(existing -> identityKey.equals(ownerMapper.identityKey(existing)));
245	        if (identityInUse) {
246	            return new ResponseEntity<>(HttpStatus.CONFLICT);
247	        }
