249	        // server's current date when none was supplied — and roll it forward to the next business
250	        // day: a Saturday or Sunday moves to the following Monday. Everything derived from the
251	        // registration date (membership-number year segment, per-day create-limit) uses this
252	        // adjusted date.
253	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
254	        if (registrationDate == null) {
255	            registrationDate = LocalDate.now();
256	        }
257	        // Reject a supplied registration date that lies in the future (later than the
258	        // server's current date): an owner cannot be registered ahead of time.
259	        else if (registrationDate.isAfter(LocalDate.now())) {
260	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
261	        }
262	        registrationDate = toBusinessDay(registrationDate);
263	        // Reject the create when the daily sign-up limit has been reached, i.e. 100 or more
264	        // owners have already been registered on this (adjusted) business day.
265	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
266	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
267	        }
268	        HttpHeaders headers = new HttpHeaders();
269	        Owner owner = candidate;
270	        owner.setRegistrationDate(registrationDate);
271	        // Assign the customer code as '<REGION>-<HASH8>': the region derived from the owner's
272	        // postcode (falling back to the city, then 'UNKNOWN') and the first 8 upper-case hex
273	        // characters of the SHA-256 of the normalized telephone concatenated with the last name.
274	        owner.setCustomerCode(customerCode(owner));
275	        // Record how many existing owners already share this owner's first and last name
276	        // (compared case-insensitively) at the moment before this owner is created.
277	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
