279	        // registered on this (adjusted) business day before this owner is created.
280	        owner.setBulkSignupWarning(countOwnersRegisteredOn(registrationDate) > 80);
281	        // Record the size of this owner's household after this create: the number of existing
282	        // owners sharing the same household (i.e. the same computed householdId) plus this owner.
283	        owner.setHouseholdSize(countHouseholdMembers(owner) + 1);
284	        // Cap this owner's membership level at one above the current maximum membership level among
285	        // their existing household members. When the owner has no existing household member no cap
286	        // applies (a null cap; see OwnerMapper#membershipLevel).
287	        owner.setMembershipLevelCap(membershipLevelCap(owner));
